mapper.select:
SELECT NOTICES_ID, NOTICES_TITLE, NOTICES_IS_PINNED, NOTICES_CREATED_AT, NOTICES_FILE_PATH, NOTICES_CONTENT
FROM notices


        AND NOTICES_TITLE = #{noticeTitle}


        AND NOTICES_CONTENT LIKE CONCAT('%', #{noticeContent}, '%')


        AND NOTICES_CREATED_AT > = #{noticeDateStart}


        AND NOTICES_CREATED_AT < = #{noticeDateEnd}

SELECT COUNT(*)
FROM notices


        AND NOTICES_TITLE = #{noticeTitle}


        AND NOTICES_CONTENT LIKE CONCAT('%', #{noticeContent}, '%')


        AND NOTICES_CREATED_AT > = #{noticeDateStart}


        AND NOTICES_CREATED_AT < = #{noticeDateEnd}
